════════ packs/basics/tasks/ci-performance/task.mjs
// basics task: ci-performance — the weekly read on where this repo's CI time goes,
// and whether it has got worse.
//
// A suite's runtime degrades the way a lawn grows: never in one visible step, so
// nobody profiles it until it is bad enough to complain about, by which point the
// cause is a dozen changes back. This task takes the measurement on a cadence
// instead, from the one ledger that cannot be argued with — the Actions run
// history — and keeps a standing record of it.
//
// CONDITIONAL HANDOFF. Code-work does the measuring, which is pure code: read the
// runs, take each workflow's median over this window and the one before, compare.
// A quiet week ends there — the record is refreshed and no agent is spent. Only a
// real regression requests the agent, which then has something worth its time: a
// named workflow, a before and after, and the ci-performance-evaluation skill's
// method for finding the cause.
//
// WHY sonnet: the finding arrives already localized to a workflow and a delta, and
// the skill states the method step by step; what remains is profiling and a bounded
// fix. Ceilinged at `open-pr`, so a change to how this repo builds or tests always
// lands in front of a reviewer.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'ci-performance',
  frequency: 'weekly',
  // Movement, not standing state: CI runtime only changes when something lands, so
  // a week with no commits and no PR activity has nothing new to measure — the same
  // runs, the same medians, the same verdict as last week.
  precondition_signals: ['commits', 'prs'],
  agent_model: 'sonnet',
  expected_outcome: 'pr',
  automerge: 'anything',             // CI itself is the gate: a fix that turns anything red cannot merge, and a green one is the point (owner, 2026-08-30)
  agent_instructions: 'task.md',
  code_work: 'node worker.mjs',
  // A couple of hundred run records plus one job breakdown, against this repo's own
  // API. Seconds in practice; the bound is for a rate-limited or wedged read.
  code_work_timeout: 300,
  // Profiling a suite means running it, more than once, in both arms of an A/B.
  agent_execution_timeout: 3600,

  precondition(signals) {
    const commits = signals.commits?.count ?? 0;
    const prs = (signals.prs?.touched ?? []).length;
    if (commits === 0 && prs === 0) {
      return { run: false, reason: 'no commits and no PR activity this week — CI ran on nothing new, so its timings cannot have moved' };
    }
    return { run: true, reason: `${commits} commit(s) and ${prs} touched PR(s) this week — re-measure CI timings and compare against the previous window` };
  },
};
════════ packs/product-wiki/tasks/wiki-growth/task.mjs
// product-wiki task: wiki-growth — one research-and-refine pass over the repo's
// product wikis (per-project-scheduling DESIGN §6). Worker: task.md.
//
// WEEKLY, not daily and not commit-gated: research arrives on the world's clock,
// not the repo's, and a nightly high-model pass economically pressures
// fabrication (the Karpathy LLM-wiki cadence). The `commits` signal is declared
// only so the precondition can note recent product-relevant movement in context;
// the run itself is scheduled by frequency, not triggered by a commit.
//
// The pending-wiki-change gate lives HERE, in the precondition (DESIGN §12: the
// precondition is the ONLY decision point — it used to be a task.md preflight,
// which was the agentic phase deciding to skip a run its precondition had
// already granted). It is not subsumed by the queue: the queue guards at most one
// live ITEM per task — it never looks at pull requests, and a completed run closes
// its item while leaving the growth PR open for review. This gate is the only thing standing between an unreviewed
// PR and a second round of research stacked on top of it.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The wiki tree, root-anchored: the prefix this precondition both declines on
// (a pending change to it) and adds context for (a landed change to it), and the
// scope of what the round's own PR may land unreviewed.
const WIKI_ROOT = 'product-wiki/';

export default {
  id: 'wiki-growth',
  frequency: 'weekly',             // fires at the weekly anchor (DESIGN §2) — the world's clock, not the repo's
  precondition_signals: ['commits', 'prs'],
  agent_model: 'opus',                   // open-web research + curation is the heaviest judgment in the task set
  expected_outcome: 'pr',
  // Markdown, and only inside the tree the round is allowed to grow: `&&` is the
  // intersection, so a doc elsewhere in the repo and a non-doc file inside the
  // wiki both park the round for review. On a member whose mount predates this
  // vocabulary the policy reads as invalid, which is the same park — never a
  // wider merge.
  automerge: [`under:${WIKI_ROOT} && doc-changes`],
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,            // open-web research is the least predictable of the tasks — very generous

  // The weekly anchor is the trigger — a wiki grows on research availability, not
  // repo activity — EXCEPT while an open PR carries a pending change to the wiki
  // tree: then this run is declined here, in code, rather than granted and
  // abandoned by the agent. Reading the pending CONTENT rather than a marker the
  // worker applied to its own PR means a human's wiki edit in flight gates the
  // round too. The worker's own stop condition (no citable material → no branch,
  // no PR) remains the legal empty OUTCOME of a run that did happen.
  precondition(signals) {
    const openPrs = signals.prs?.open ?? [];
    const pendingWikiPr = openPrs
      .find((p) => Array.isArray(p.changedPaths) && p.changedPaths.some((f) => f.startsWith(WIKI_ROOT)));
    if (pendingWikiPr) {
      return {
        run: false,
        reason: `PR #${pendingWikiPr.number} has a pending ${WIKI_ROOT} change — research waits for its review, so a second unreviewed round is never stacked on it`,
      };
    }
    // A PR whose paths could not be read (an unreadable file list, or an engine
    // older than the one that resolves them) is UNKNOWN, never "clear": the whole
    // point of the gate is that an unreviewed round is worse than a skipped one.
    const opaquePr = openPrs.find((p) => !Array.isArray(p.changedPaths));
    if (opaquePr) {
      return {
        run: false,
        reason: `PR #${opaquePr.number}'s changed paths could not be read, so whether a ${WIKI_ROOT} change is pending is unknown — a skipped round is cheaper than an unreviewed one stacked on it`,
      };
    }
    const touched = signals.commits?.touchedPaths ?? [];
    const wikiMoved = touched.some((p) => p.startsWith(WIKI_ROOT));
    const context = wikiMoved
      ? ['The product-wiki tree moved in the window — spot-check any pages whose cited claims the change may have superseded.']
      : [];
    return { run: true, reason: 'weekly product-wiki growth pass', context };
  },
};
════════ packs/tidy-repo/tasks/tidy-prs/task.mjs
// tidy-repo task: tidy-prs — the read-only PR half of the tidy sweep
// (per-project-scheduling DESIGN §6). One weekly full sweep over every open PR:
// which should stay open, which are closeable. Recommends; never closes. Worker:
// task.md. Issues are a separate task — one dimension per task, each with its own
// trigger, scope, and tracker, so there is no ordering barrier.
//
// WEEKLY, and full every time it runs — but it only runs when a PR actually moved
// in the window. A PR verdict is a standing recommendation for a human, not a
// same-day alert, so re-deriving the whole picture once a week beats a daily partial
// one — and "weekly" is a frequency DECLARATION, never a gate trick inside a daily
// task (DESIGN §3). What "full" does not mean is unconditional: an untouched set of
// open PRs yields last week's verdicts again, so the sweep is gated on newness even
// though its scope stays full.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'tidy-prs',
  frequency: 'weekly',                      // the weekly anchor (DESIGN §2); the full sweep is the declaration
  precondition_signals: ['prs'],            // the open set is the scope; `touched` is the gate
  agent_model: 'sonnet',                    // superseded / already-in-main are judgment calls on the diff
  expected_outcome: 'none',                 // assess-only: never closes, merges, or comments on a PR; writes only its tracker
  agent_instructions: 'task.md',
  agent_execution_timeout: 900,             // a full sweep, but one cheap read-only verdict per PR

  // Two gates, in order. Is there anything open to assess — a repo with no open PRs
  // stays silent. Then: did any open PR get opened or updated in the window. If none
  // did, the picture is the one the tracker already holds and another pass would
  // rewrite it with itself. When one did move, scope is still the FULL open set: a
  // PR verdict is relative to the others (superseded-by), so the mover cannot be
  // judged alone. `touched` counts the newly OPENED ones too — the collector derives
  // it from the open listing's `updated_at`, which a new PR carries.
  precondition(signals) {
    const open = (signals.prs?.open ?? []).map((p) => p.number);
    if (!open.length) return { run: false, reason: 'no open PRs' };

    const touched = signals.prs?.touched ?? [];
    if (!touched.length) {
      return { run: false, reason: `no PR opened or updated in the window — the standing picture over ${open.length} open PR(s) is unchanged` };
    }

    return {
      run: true,
      reason: `${touched.length} PR(s) moved in the window — full sweep over ${open.length} open PR(s)`,
      context: [`PRs to assess (read-only — recommend closes, never close): ${open.map((n) => `#${n}`).join(', ')}.`],
    };
  },
};
════════ packs/tidy-repo/tasks/improve-comments/task.mjs
// tidy-repo task: improve-comments — the one tidy dimension whose subject is the
// repo's own source rather than its GitHub objects. The other three assess or act
// on issues, PRs and branches; this one reads a slice of the code AS COMMENTS and
// fixes what it finds there. Worker: task.md, which runs the improve-comments skill
// and nothing else.
//
// WHY IT IS A TASK AT ALL: a comment decays as the code around it changes and
// nothing makes it fail. No test goes red, no check fires, and no session working on
// something else will stop to fix one. The only way a repo's comments get read as
// comments is a pass whose whole job that is.
//
// WEEKLY. Comment drift is not latency-sensitive — a stale comment costs the next
// reader, whenever that is — and the window's commits are what name the files whose
// comments are likeliest wrong, so a weekly window is a bigger and better-targeted
// scope than a daily one for the same session cost.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The pinned commit subject the run's own scope gate keys on, stated in task.md and
// enforced by the skill's `improve-comments-scope` check. Kept in step by the
// declaration test beside this pack's other tests.
const RUN_TITLE = 'Claudinite tidy: improve comments';

// The mount, excluded from every round's scope. `.claudinite/shared/` is vendored
// and the next converge replaces it whole, so a comment improved there is gone by
// morning; `.claudinite/local/` is written by the growth tasks. Neither is the
// repo's own source, and the converge touches them most nights, so left in they
// crowd the round's cap. Kept in step with the same prefix in the
// improve-comments-scope gate by the test beside that check.
const MOUNT_PREFIX = '.claudinite/';

// How many of the window's changed files one round reads. A busy week can touch
// hundreds, and a session handed all of them skims; the rest are next round's, and
// the run says so rather than presenting a truncated list as the whole window.
const MAX_FILES = 40;

export default {
  id: 'improve-comments',
  frequency: 'weekly',                   // the weekly anchor (DESIGN §2); the window's commits are the scope
  precondition_signals: ['commits', 'prs'],
  agent_model: 'opus',                   // whether a comment carries a why the code cannot state is the judgment here, and a wrong call lands in the repo's source
  // A ceiling, not a plan: the repo's own delivery setting decides whether the
  // PR lands unreviewed, and a `review` member still gets it left open. The
  // policy states in the contract what makes the pass safe to land unattended —
  // the diff can only ever be comment text and README content — and the pass's
  // own scope gate (the skill's `improve-comments-scope` check) reds the same
  // boundary on every branch wearing its title, armed or not.
  expected_outcome: 'pr',
  automerge: ['comment-only-changes', 'readme-changes'],
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,

  // Two gates, in order. Did anything land in the window — comments decay against
  // code, so a quiet week has nothing to re-read. Then: is this pass's previous PR
  // still open, which means it did not land (a `review` member's, or one whose CI
  // never concluded), and a second sweep over files the first one may already have
  // touched would stack on it. Reading the pending PR's TITLE rather than a marker
  // on the item means a PR the owner opened by hand from this branch gates the
  // round too.
  precondition(signals) {
    const openPrs = signals.prs?.open ?? [];
    const pending = openPrs.find((p) => String(p.title ?? '').startsWith(RUN_TITLE));
    if (pending) {
      return {
        run: false,
        reason: `PR #${pending.number} is this pass's previous round, still open — this round waits for it to land rather than stack a second sweep on it`,
      };
    }

    const commits = signals.commits;
    if (!commits?.substantiveChange) {
      return { run: false, reason: 'no substantive commit in the window — nothing moved for a comment to have drifted from' };
    }
    const allTouched = commits.touchedPaths ?? [];
    if (!allTouched.length) {
      return { run: false, reason: 'the window\'s commits name no changed path — nothing to read' };
    }
    const touched = allTouched.filter((p) => !p.startsWith(MOUNT_PREFIX));
    if (!touched.length) {
      return { run: false, reason: `the window's changed paths are all under ${MOUNT_PREFIX} — the mount is not this repo's source to comment` };
    }

    // A window can carry more files than one session should read as comments. Name
    // the cap and what it dropped rather than hand over a silently truncated list
    // that reads as the whole window.
    const scope = touched.slice(0, MAX_FILES);
    const dropped = touched.length - scope.length;
    return {
      run: true,
      reason: `${touched.length} path(s) changed in the window`,
      context: [
        `Read the comments in exactly these files, and no others: ${scope.join(', ')}.`,
        ...(dropped ? [`${dropped} further path(s) changed in the window and are NOT in scope this round — say so in the wrap-up so the next round is not read as a full sweep.`] : []),
        'A file whose comments are already right yields no edit — that is the common outcome and a good one.',
      ],
    };
  },
};

