  return {
    manifestVersion: readManifestVersion(root),
    shipsReleasePipeline: readShipsReleasePipeline(root),
    hasLocalPacks: readHasLocalPacks(root),
    retentionDays: readRetentionDays(packIds, packConfigFor),
  };
