input.command:
node -e "
const {execSync}=require('child_process');
const files=execSync(\"git ls-files 'packs/*/tasks/*/task.mjs' 'packs/*/queue/tasks/*/task.mjs'\",{encoding:'utf8'}).trim().split('\n');
const rows=[];
for(const f of files){const t=(await import('./'+f)).default;
rows.push({id:t.id,pack:f.split('/')[1],freq:t.frequency,model:t.agent_model,sig:(t.precondition_signals||[]).join('+')||'—'});}
const ord={hourly:0,daily:1,'daily+1h':1,'daily-1h':1,'daily-2h':1,weekly:2,monthly:3,manual:4};
rows.sort((a,b)=>(ord[a.freq]-ord[b.freq])||a.id.localeCompare(b.id));
for(const r of rows)console.log([r.freq.padEnd(8),r.model.padEnd(6),r.id.padEnd(24),r.sig].join(' '));
" 2>&1 | tail -30

